create extension if not exists pgcrypto;
create type public.app_role as enum ('ADMIN','MANAGER','EMPLOYEE');
create type public.agreement_status as enum ('DRAFT','PENDING_EMPLOYEE','PENDING_REPRESENTATIVE','COMPLETED','REJECTED','EXPIRED','CANCELLED');
create type public.agreement_party_role as enum ('EMPLOYEE','REPRESENTATIVE');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, email text not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_roles (user_id uuid primary key references public.profiles(id) on delete cascade, role public.app_role not null, created_at timestamptz not null default now());
create table public.manager_employee_assignments (manager_id uuid references public.profiles(id) on delete cascade, employee_id uuid references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(manager_id, employee_id));
create table public.agreement_templates (id uuid primary key default gen_random_uuid(), name text not null, type text not null, version integer not null default 1, body text not null, is_active boolean not null default true, created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), unique(name, version));
create table public.agreements (id uuid primary key default gen_random_uuid(), reference_no text not null unique, title text not null, type text not null, status public.agreement_status not null default 'DRAFT', version integer not null default 1, snapshot jsonb not null default '{}', terms_hash text, created_by uuid not null references public.profiles(id), issued_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.agreement_parties (id uuid primary key default gen_random_uuid(), agreement_id uuid not null references public.agreements(id) on delete cascade, user_id uuid not null references public.profiles(id), party_role public.agreement_party_role not null, signed_at timestamptz, unique(agreement_id, party_role), unique(agreement_id, user_id, party_role));
create table public.biometric_consents (id uuid primary key default gen_random_uuid(), agreement_id uuid not null references public.agreements(id) on delete cascade, user_id uuid not null references public.profiles(id), consent_version text not null, granted_at timestamptz, withdrawn_at timestamptz, unique(agreement_id,user_id));
create table public.biometric_events (id uuid primary key default gen_random_uuid(), agreement_id uuid not null references public.agreements(id) on delete cascade, user_id uuid not null references public.profiles(id), method text not null, result text not null, provider_reference text, created_at timestamptz not null default now());
create table public.signature_events (id uuid primary key default gen_random_uuid(), agreement_id uuid not null references public.agreements(id) on delete cascade, user_id uuid not null references public.profiles(id), party_role public.agreement_party_role not null, agreement_version integer not null, signature_hash text not null, created_at timestamptz not null default now(), unique(agreement_id, party_role));
create table public.agreement_files (id uuid primary key default gen_random_uuid(), agreement_id uuid not null references public.agreements(id) on delete cascade, storage_path text not null, sha256 text not null, mime_type text not null default 'application/pdf', created_at timestamptz not null default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(), agreement_id uuid references public.agreements(id) on delete set null, actor_id uuid references public.profiles(id) on delete set null, event_type text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, agreement_id uuid references public.agreements(id) on delete set null, type text not null, status text not null default 'PENDING', payload jsonb not null default '{}', created_at timestamptz not null default now());
create table public.signing_sessions (id uuid primary key default gen_random_uuid(), agreement_id uuid not null references public.agreements(id) on delete cascade, user_id uuid not null references public.profiles(id), party_role public.agreement_party_role not null, version integer not null, expires_at timestamptz not null, consumed_at timestamptz, created_at timestamptz not null default now());
create index agreements_status_idx on public.agreements(status); create index audit_events_agreement_idx on public.audit_events(agreement_id, created_at desc);

alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.agreements enable row level security; alter table public.agreement_parties enable row level security; alter table public.signature_events enable row level security; alter table public.audit_events enable row level security;
create policy profiles_self_read on public.profiles for select using (id = auth.uid());
create policy agreements_party_read on public.agreements for select using (exists(select 1 from public.agreement_parties p where p.agreement_id = id and p.user_id = auth.uid()));
create policy signature_party_read on public.signature_events for select using (user_id = auth.uid());
create policy audit_party_read on public.audit_events for select using (actor_id = auth.uid());
